/**
 * QuizLens AI - DOM Context Extractor
 * When the user selects only the question, this module traverses nearby DOM nodes
 * to locate and extract the corresponding options (A, B, C, D).
 */

import { QuestionData, QuestionOptions } from '../shared/types';
import { normalizeText, parseQuestionFromText } from './question-detector';

const EXPECTED_OPTIONS = ['A', 'B', 'C', 'D', 'E'] as const;

/**
 * Searches the DOM tree surrounding a selection Range to extract question and options
 */
export function extractOptionsFromDOM(
  selectedQuestionText: string,
  range: Range
): QuestionData | null {
  try {
    let startNode: Node | null = range.commonAncestorContainer;
    if (startNode.nodeType === Node.TEXT_NODE) {
      startNode = startNode.parentElement;
    }

    if (!startNode || !(startNode instanceof HTMLElement)) {
      return null;
    }

    // Strategy 1: Ascend up the DOM tree and check container innerText
    // Common question wrappers: .question, .quiz-item, fieldset, li, tr, form, div, section
    let currentContainer: HTMLElement | null = startNode;
    let depth = 0;
    const maxDepth = 6;

    while (currentContainer && currentContainer !== document.body && depth < maxDepth) {
      const containerText = normalizeText(currentContainer.innerText || currentContainer.textContent || '');

      // Check if container contains the selected question text
      if (containerText && containerText.includes(selectedQuestionText.trim())) {
        // Attempt parsing question and options from this container text
        const parsed = parseQuestionFromText(containerText);
        if (parsed) {
          return {
            question: selectedQuestionText.trim().length > 5 ? selectedQuestionText.trim() : parsed.question,
            options: parsed.options,
            rawText: containerText
          };
        }

        // Strategy 2: Look for structured choice elements inside this container
        const structured = extractFromStructuredElements(currentContainer, selectedQuestionText);
        if (structured) {
          return structured;
        }
      }

      currentContainer = currentContainer.parentElement;
      depth++;
    }

    // Strategy 3: Check next siblings of the question element
    const siblingResult = extractFromNextSiblings(startNode, selectedQuestionText);
    if (siblingResult) {
      return siblingResult;
    }

    return null;
  } catch (error) {
    // Fail gracefully on unexpected DOM structures
    return null;
  }
}

/**
 * Strategy 2: Extract from standard quiz DOM patterns
 * (e.g., radio buttons, labels, li elements, .option, .choice classes)
 */
function extractFromStructuredElements(
  container: HTMLElement,
  questionText: string
): QuestionData | null {
  const optionsMap: Partial<QuestionOptions> = {};

  // Check list items or option-like elements
  const candidateSelectors = [
    'li',
    '.option',
    '.choice',
    '.answer',
    '.answer-item',
    '.quiz-option',
    'label',
    '.form-check',
    'div[role="radio"]'
  ];

  for (const selector of candidateSelectors) {
    const elements = Array.from(container.querySelectorAll(selector));
    if (elements.length >= 4) {
      const foundOptions: Partial<QuestionOptions> = {};

      for (const el of elements) {
        const text = normalizeText((el as HTMLElement).innerText || el.textContent || '');
        const match = text.match(/^[\(\[]?([A-Da-d])[\)\].:\-\s]\s*(.*)$/s);
        if (match) {
          const letter = match[1].toUpperCase() as keyof QuestionOptions;
          const content = match[2].trim();
          if (content && EXPECTED_OPTIONS.includes(letter as any)) {
            foundOptions[letter] = content;
          }
        }
      }

      // Check if we captured at least A and B
      if (foundOptions.A && foundOptions.B) {
        return {
          question: questionText.trim(),
          options: {
            A: foundOptions.A,
            B: foundOptions.B,
            ...(foundOptions.C ? { C: foundOptions.C } : {}),
            ...(foundOptions.D ? { D: foundOptions.D } : {}),
            ...(foundOptions.E ? { E: foundOptions.E } : {})
          }
        };
      }
    }
  }

  // Also check if there are 2 to 5 inputs/labels inside container without explicit A, B, C, D labels
  const radioLabels = Array.from(container.querySelectorAll('label'));
  if (radioLabels.length >= 2 && radioLabels.length <= 5) {
    const letters: Array<keyof QuestionOptions> = ['A', 'B', 'C', 'D', 'E'];
    const autoMapped: Partial<QuestionOptions> = {};

    let allValid = true;
    for (let i = 0; i < radioLabels.length; i++) {
      const text = normalizeText(radioLabels[i].innerText || radioLabels[i].textContent || '')
        .replace(/^[A-Ea-e][\)\].:\-]\s*/, '')
        .trim();
      if (!text) {
        allValid = false;
        break;
      }
      autoMapped[letters[i]] = text;
    }

    if (allValid && autoMapped.A && autoMapped.B) {
      return {
        question: questionText.trim(),
        options: {
          A: autoMapped.A,
          B: autoMapped.B,
          ...(autoMapped.C ? { C: autoMapped.C } : {}),
          ...(autoMapped.D ? { D: autoMapped.D } : {}),
          ...(autoMapped.E ? { E: autoMapped.E } : {})
        }
      };
    }
  }

  return null;
}

/**
 * Strategy 3: Check consecutive sibling elements following the question element
 */
function extractFromNextSiblings(
  questionElement: HTMLElement,
  questionText: string
): QuestionData | null {
  let sibling = questionElement.nextElementSibling;
  const collectedTextLines: string[] = [];
  let steps = 0;

  while (sibling && steps < 10) {
    const text = normalizeText((sibling as HTMLElement).innerText || sibling.textContent || '');
    if (text) {
      collectedTextLines.push(text);
    }
    sibling = sibling.nextElementSibling;
    steps++;
  }

  if (collectedTextLines.length > 0) {
    const fullText = `${questionText}\n${collectedTextLines.join('\n')}`;
    const parsed = parseQuestionFromText(fullText);
    if (parsed) {
      return {
        question: questionText.trim(),
        options: parsed.options,
        rawText: fullText
      };
    }
  }

  return null;
}

