/**
 * QuizLens AI - Selection & Interaction Controller
 * Captures user text selection, debounces, prevents duplicate requests,
 * coordinates detection and displays result popup.
 */

import { detectQuestion } from './question-detector';
import { ResultPopup } from './result-popup';
import { QuestionData, ExtensionSettings, AnswerResult } from '../shared/types';
import { DEFAULT_SETTINGS } from '../shared/constants';

export class SelectionController {
  private popup: ResultPopup;
  private debounceTimer: number | null = null;
  private lastProcessedHash: string = '';
  private isProcessing: boolean = false;
  private settings: ExtensionSettings = DEFAULT_SETTINGS;

  constructor() {
    this.popup = new ResultPopup();
    this.loadSettings();
    this.attachEventListeners();
    this.listenToSettingsChanges();
  }

  private loadSettings(): void {
    if (typeof chrome !== 'undefined' && chrome.runtime?.sendMessage) {
      chrome.runtime.sendMessage({ type: 'GET_SETTINGS' }, (response) => {
        if (chrome.runtime.lastError) return;
        if (response?.success && response.data) {
          this.settings = { ...DEFAULT_SETTINGS, ...response.data };
        }
      });
    }
  }

  private listenToSettingsChanges(): void {
    if (typeof chrome !== 'undefined' && chrome.storage?.onChanged) {
      chrome.storage.onChanged.addListener((changes, area) => {
        if (area === 'sync' || area === 'local') {
          if (changes.settings && changes.settings.newValue) {
            this.settings = { ...DEFAULT_SETTINGS, ...changes.settings.newValue };
          }
        }
      });
    }
  }

  private attachEventListeners(): void {
    // Listen for mouse selection
    document.addEventListener('mouseup', (event: MouseEvent) => {
      // Don't trigger if user clicked inside our popup
      const target = event.target as HTMLElement;
      if (target?.closest && target.closest('#quizlens-root-container')) {
        return;
      }
      this.handleSelectionChange();
    });

    // Listen for keyboard selection (Shift + arrows, Ctrl+A)
    document.addEventListener('keyup', (event: KeyboardEvent) => {
      if (event.shiftKey || event.key === 'ArrowUp' || event.key === 'ArrowDown' || event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        this.handleSelectionChange();
      }
    });
  }

  private handleSelectionChange(): void {
    if (!this.settings.enabled) return;

    if (this.debounceTimer) {
      window.clearTimeout(this.debounceTimer);
    }

    this.debounceTimer = window.setTimeout(() => {
      this.processCurrentSelection();
    }, this.settings.debounceMs || 400);
  }

  private computeHash(text: string): string {
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      const char = text.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash |= 0;
    }
    return hash.toString();
  }

  public async processCurrentSelection(): Promise<void> {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
      return;
    }

    const selectedText = selection.toString().trim();
    if (!selectedText || selectedText.length < 5) {
      return;
    }

    const currentHash = this.computeHash(selectedText);
    // Avoid re-processing the exact same text if recently completed
    if (currentHash === this.lastProcessedHash && !this.isProcessing) {
      return;
    }

    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();

    // Check if rect is visible
    if (rect.width === 0 && rect.height === 0) {
      return;
    }

    // Run question detection
    const detection = detectQuestion(selectedText, range);

    if (!detection.isValid || !detection.data) {
      // If user selected normal text, do nothing to avoid annoying the user
      return;
    }

    // Valid question detected!
    this.lastProcessedHash = currentHash;
    this.isProcessing = true;

    // Show loading UI immediately
    this.popup.showLoading(rect);

    try {
      const answerResult = await this.requestAnswer(detection.data);
      this.isProcessing = false;

      if (!answerResult) {
        this.popup.showError('Không nhận được phản hồi từ AI', rect);
        return;
      }

      if (answerResult.status === 'SUCCESS' && answerResult.answer) {
        this.popup.showResult(answerResult, rect, this.settings.autoCopy);
      } else {
        this.popup.showUnknown(rect, 'AI không tìm được đáp án chắc chắn cho câu hỏi này.');
      }
    } catch (error: any) {
      this.isProcessing = false;
      const message = error?.message || 'Lỗi kết nối đến Backend hoặc AI Provider.';
      this.popup.showError(message, rect);
    }
  }

  private requestAnswer(questionData: QuestionData): Promise<AnswerResult | null> {
    return new Promise((resolve, reject) => {
      if (typeof chrome === 'undefined' || !chrome.runtime?.sendMessage) {
        reject(new Error('Chrome Extension API không khả dụng'));
        return;
      }

      chrome.runtime.sendMessage(
        {
          type: 'ANALYZE_QUESTION',
          payload: {
            question: questionData.question,
            options: questionData.options
          }
        },
        (response) => {
          if (chrome.runtime.lastError) {
            reject(new Error(chrome.runtime.lastError.message || 'Lỗi gửi tin nhắn nội bộ'));
            return;
          }

          if (!response || !response.success) {
            reject(new Error(response?.error || 'Lỗi từ máy chủ QuizLens AI'));
            return;
          }

          resolve(response.data as AnswerResult);
        }
      );
    });
  }
}

