/**
 * QuizLens AI - Question Detector
 * Accurately detects and parses multiple-choice questions (Vietnamese & English)
 * with 4 options (A, B, C, D). Supports math formulas, code blocks, multiline options.
 */

import { QuestionData, QuestionOptions } from '../shared/types';
import { extractOptionsFromDOM } from './dom-extractor';

export interface DetectionResult {
  isValid: boolean;
  data: QuestionData | null;
  reason?: string;
}

/**
 * Standard option letters we expect
 */
const EXPECTED_OPTIONS = ['A', 'B', 'C', 'D', 'E'] as const;

/**
 * Regex patterns to detect option prefixes:
 * - A. or a.
 * - A) or a)
 * - (A) or (a)
 * - [A] or [a]
 * - A: or a:
 * - A - or a -
 * - • A. or * A. or - A.
 */
const OPTION_PREFIX_REGEX = /(?:^|[\r\n]+|[•\*\-\–\—\+·]\s*|\s{2,}|\t)(?:[\(\[]?([A-Ea-e])[\)\].:\-]\s*)|(?:\s+)([A-Ea-e])[\.:\-]\s*/g;

/**
 * Normalizes text: cleans excessive whitespace while preserving code indentation and line breaks
 */
export function normalizeText(text: string): string {
  if (!text) return '';
  return text
    .replace(/\u00a0/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

/**
 * Checks if a string looks like a standard prose paragraph or website navigation/heading,
 * rather than an educational or exam multiple-choice question.
 */
function isDisqualifiedNonQuestion(text: string): boolean {
  const trimmed = text.trim();
  // Too short to be a real question + 4 options
  if (trimmed.length < 15) return true;

  // Header/navigation noise
  const noisePatterns = [
    /^(menu|navigation|trang chủ|home|contact|giới thiệu|about us|footer|bản quyền|copyright)/i,
    /^(điều khoản|chính sách bảo mật|terms of service|privacy policy)/i,
    /^(đăng nhập|đăng ký|sign in|sign up|log in|register)$/i
  ];

  return noisePatterns.some((pattern) => pattern.test(trimmed));
}

/**
 * Parses selected text directly into Question + 4 Options
 */
export function parseQuestionFromText(rawText: string): QuestionData | null {
  const text = normalizeText(rawText);
  if (!text || isDisqualifiedNonQuestion(text)) {
    return null;
  }

  // Find all option positions and letters in text
  const matches: Array<{ letter: string; index: number; fullMatchLength: number }> = [];
  const regex = new RegExp(OPTION_PREFIX_REGEX);
  let match: RegExpExecArray | null;

  while ((match = regex.exec(text)) !== null) {
    const rawLetter = match[1] || match[2];
    if (!rawLetter) continue;
    const letter = rawLetter.toUpperCase();
    // Offset index to where the option label actually starts (skip leading newline/space)
    const matchStart = match.index + (match[0].length - match[0].trimStart().length);
    matches.push({
      letter,
      index: matchStart,
      fullMatchLength: match[0].trimStart().length
    });
  }

  // Need at least 2 option markers
  if (matches.length < 2) {
    return null;
  }

  // Deduplicate matches: if same letter appears multiple times, keep the latest one
  const lastSeenIndexByLetter = new Map<string, number>();
  for (let i = 0; i < matches.length; i++) {
    lastSeenIndexByLetter.set(matches[i].letter, i);
  }
  const filteredIndices = new Set(lastSeenIndexByLetter.values());
  const validMatches = matches.filter((_, idx) => filteredIndices.has(idx));

  // Must contain at least A and B
  const uniqueLetters = new Set(validMatches.map((m) => m.letter));
  if (!uniqueLetters.has('A') || !uniqueLetters.has('B')) {
    return null;
  }

  // Identify the question portion (everything before the first option match)
  const firstOptionIndex = validMatches[0].index;
  const questionPart = text.slice(0, firstOptionIndex).trim();

  // If question part is empty or too short (less than 5 chars), invalid
  if (questionPart.length < 5) {
    return null;
  }

  // Extract options text
  const optionsMap: Partial<QuestionOptions> = {};

  for (let i = 0; i < validMatches.length; i++) {
    const current = validMatches[i];
    const next = validMatches[i + 1];
    const startIndex = current.index + current.fullMatchLength;
    const endIndex = next ? next.index : text.length;

    const content = text.slice(startIndex, endIndex).trim();
    if (!content) {
      // Option has empty content
      return null;
    }

    if (EXPECTED_OPTIONS.includes(current.letter as any)) {
      optionsMap[current.letter as keyof QuestionOptions] = content;
    }
  }

  // Validate that at least A and B are populated
  if (!optionsMap.A || !optionsMap.B) {
    return null;
  }

  return {
    question: questionPart,
    options: {
      A: optionsMap.A,
      B: optionsMap.B,
      ...(optionsMap.C ? { C: optionsMap.C } : {}),
      ...(optionsMap.D ? { D: optionsMap.D } : {}),
      ...(optionsMap.E ? { E: optionsMap.E } : {})
    },
    rawText: text
  };
}

/**
 * Main detection entry point.
 * 1. Checks if selected text contains question + options.
 * 2. If not, inspects DOM context around selection to find nearby options.
 */
export function detectQuestion(
  selectionText: string,
  selectionRange?: Range | null
): DetectionResult {
  const normalized = normalizeText(selectionText);

  if (!normalized || normalized.length < 5) {
    return { isValid: false, data: null, reason: 'Selection text too short' };
  }

  // Step 1: Try direct text parsing
  const directResult = parseQuestionFromText(normalized);
  if (directResult) {
    return {
      isValid: true,
      data: directResult
    };
  }

  // Step 2: Try DOM extraction if a DOM range is available
  if (selectionRange) {
    const domExtracted = extractOptionsFromDOM(normalized, selectionRange);
    if (domExtracted) {
      return {
        isValid: true,
        data: domExtracted
      };
    }
  }

  return {
    isValid: false,
    data: null,
    reason: 'Could not extract 4 valid options (A, B, C, D)'
  };
}

